import React, { useState, useEffect } from 'react';
import ScarewareSimulation from './components/ScarewareSimulation';
import EducationalInfo from './components/EducationalInfo';
import WarningBanner from './components/WarningBanner';

interface SimulationState {
  isActive: boolean;
  currentPhase: 'intro' | 'popup' | 'scan' | 'fullscreen' | 'persistence' | 'hijacking' | 'escape';
  showEducationalInfo: boolean;
}

const App: React.FC = () => {
  const [simulationState, setSimulationState] = useState<SimulationState>({
    isActive: false,
    currentPhase: 'intro',
    showEducationalInfo: false,
  });

  const startSimulation = () => {
    setSimulationState(prev => ({
      ...prev,
      isActive: true,
      currentPhase: 'popup'
    }));
  };

  const stopSimulation = () => {
    setSimulationState({
      isActive: false,
      currentPhase: 'intro',
      showEducationalInfo: false,
    });
  };

  const showEducationalInfo = () => {
    setSimulationState(prev => ({
      ...prev,
      showEducationalInfo: true
    }));
  };

  const hideEducationalInfo = () => {
    setSimulationState(prev => ({
      ...prev,
      showEducationalInfo: false
    }));
  };

  const advancePhase = (phase: SimulationState['currentPhase']) => {
    setSimulationState(prev => ({
      ...prev,
      currentPhase: phase
    }));
  };

  return (
    <div className="simulation-container">
      <WarningBanner />
      
      {!simulationState.isActive ? (
        <div className="simulation-content">
          <h1>🚨 Scareware Simulation - Educational Tool</h1>
          
          <div className="escape-info">
            <h3>⚠️ Important: This is a Safe Educational Simulation</h3>
            <p>
              This website demonstrates common scareware techniques in a controlled, 
              educational environment. You are completely safe and can exit at any time.
            </p>
          </div>

          <div style={{ margin: '2rem 0' }}>
            <h2>What You'll Learn</h2>
            <ul style={{ margin: '1rem 0', paddingLeft: '2rem' }}>
              <li>How scareware creates fake security alerts</li>
              <li>Common browser hijacking techniques</li>
              <li>How to identify and avoid real threats</li>
              <li>Proper escape procedures for real situations</li>
              <li>What to do if you encounter actual scareware</li>
            </ul>
          </div>

          <div style={{ margin: '2rem 0' }}>
            <button 
              className="button button-primary" 
              onClick={startSimulation}
              style={{ marginRight: '1rem' }}
            >
              Start Simulation
            </button>
            <button 
              className="button button-success" 
              onClick={showEducationalInfo}
            >
              Learn More First
            </button>
          </div>

          <div style={{ 
            background: '#f8f9fa', 
            padding: '1.5rem', 
            borderRadius: '8px',
            marginTop: '2rem'
          }}>
            <h3>Safety Features</h3>
            <ul style={{ margin: '1rem 0', paddingLeft: '2rem' }}>
              <li>✅ Clear "SIMULATION" indicators throughout</li>
              <li>✅ Easy exit buttons always available</li>
              <li>✅ Educational information at every step</li>
              <li>✅ No actual system changes or downloads</li>
              <li>✅ Safe for all ages and experience levels</li>
            </ul>
          </div>
        </div>
      ) : (
        <ScarewareSimulation
          currentPhase={simulationState.currentPhase}
          onAdvancePhase={advancePhase}
          onStop={stopSimulation}
          onShowEducationalInfo={showEducationalInfo}
        />
      )}

      {simulationState.showEducationalInfo && (
        <EducationalInfo onClose={hideEducationalInfo} />
      )}
    </div>
  );
};

export default App;
